  "sim.egg-incubator.title": "Incubadora de Ovos",
  "sim.egg-incubator.desc": "Gerencie a temperatura, humidade e rotação dos ovos numa incubadora para maximizar a taxa de eclosão.",
  "sim.dairy-farm.title": "Fazenda de Laticínios",
  "sim.dairy-farm.desc": "Administre uma pequena exploração de laticínios: horários de alimentação, ciclos de ordenha e saúde do rebanho para maximizar a produção.",
  "sim.poultry-farm.title": "Fazenda de Avicultura",
  "sim.poultry-farm.desc": "Administre uma exploração avícola comercial — alimentação, saúde e metas de produção para bandos de frangos e poedeiras.",
  "sim.cattle-dairy.title": "Gado e Laticínios",
  "sim.cattle-dairy.desc": "Supervisione uma quinta de gado e uma unidade de laticínios, equilibrando gestão de pastagens, reprodução e produção de leite.",
  "sim.sheep-farm.title": "Fazenda de Ovelhas",
  "sim.sheep-farm.desc": "Administre uma fazenda de ovelhas através de ciclos sazonais: reprodução, tosquia e vendas ao mercado.",
  "sim.network-noc.title": "NOC de Rede",
  "sim.network-noc.desc": "Atue como engenheiro do Centro de Operações de Rede — diagnostique e resolva incidentes de infraestrutura em tempo real sob pressão.",
  "sim.mobile-repair.title": "Oficina de Reparação Móvel",
  "sim.mobile-repair.desc": "Diagnostique e repare smartphones — substituições de ecrã, problemas de bateria e falhas na placa-mãe.",
  "sim.laptop-repair.title": "Oficina de Reparação de Portáteis",
  "sim.laptop-repair.desc": "Resolva e repare portáteis: falhas de hardware, problemas de BIOS e substituições de componentes.",
  "sim.perfume-lab.title": "Laboratório de Perfumes",
  "sim.perfume-lab.desc": "Misture óleos essenciais e compostos aromáticos para criar fragrâncias exclusivas e atingir benchmarks de qualidade.",
  "sim.detergent-lab.title": "Laboratório de Detergente",
  "sim.detergent-lab.desc": "Formule produtos de limpeza — equilibre tensoativos, cargas e testes de desempenho dentro do orçamento.",
  "sim.skin-care-lab.title": "Laboratório de Cuidados com a Pele",
  "sim.skin-care-lab.desc": "Desenvolva e teste formulações cosméticas, cumprindo padrões de segurança e metas de eficácia.",
  "sim.woodworking.title": "Oficina de Marcenaria",
  "sim.woodworking.desc": "Administre uma oficina de marcenaria personalizada: planeie trabalhos, gerencie materiais e entregue mobiliário no prazo e dentro do orçamento.",
  "sim.aluminum-glazing.title": "Alumínio e Vidraçaria",
  "sim.aluminum-glazing.desc": "Gerencie um negócio de fabricação em alumínio e instalação de vidro, do orçamento à conclusão no local.",
  "sim.global-kitchen.title": "Cozinha Global",
  "sim.global-kitchen.desc": "Lidere uma cozinha de restaurante: gerencie menus, equipa, custos e satisfação do cliente em turnos de serviço.",
  "sim.chocolate-factory.title": "Fábrica de Chocolate",
  "sim.chocolate-factory.desc": "Operar uma fábrica de confeitaria — fornecimento de cacau, programação da produção e controlo de qualidade.",
  "sim.solar-energy.title": "Central de Energia Solar",
  "sim.solar-energy.desc": "Desenhe e opere uma instalação solar — dimensione painéis, gerencie a exportação para a rede e acompanhe o ROI.",
  "sim.hvac-systems.title": "Sistemas de HVAC",
  "sim.hvac-systems.desc": "Instale e mantenha sistemas de aquecimento, ventilação e ar-condicionado para edifícios comerciais.",
  "sim.logistics-supply.title": "Logística e Cadeia de Abastecimento",
  "sim.logistics-supply.desc": "Otimize operações de armazém, rotas da frota e relações com fornecedores para atingir KPIs de entrega.",
  "sim.barber-salon.title": "Salão de Barbearia",
  "sim.barber-salon.desc": "Administre uma barbearia: marcações, horários da equipa, preços e estratégias de retenção de clientes.",
  "sim.board-surgeon.title": "Cirurgião de Prontidão",
  "sim.board-surgeon.desc": "Tome decisões cirúrgicas de alto risco numa sala de operações simulada — gestão do tempo e segurança do paciente.",
  "sim.english-journey.title": "Jornada em Inglês",
  "sim.english-journey.desc": "Guie os alunos por um programa estruturado de inglês, adaptando-se a diferentes níveis de habilidade.",
  "sim.music-training.title": "Estúdio de Treino Musical",
  "sim.music-training.desc": "Administre uma escola de música: programe aulas, gerencie instrumentos e acompanhe o progresso dos alunos até as récitas.",
  "sim.trade-tycoon.title": "Trade Tycoon",
  "sim.trade-tycoon.desc": "Construa um império de negociações — compre barato, venda caro, gerencie inventário e fluxo de caixa em vários mercados.",
  "sim.vehicle-diagnostics.title": "Simulador de diagnóstico e reparação do veículo",
  "sim.vehicle-diagnostics.desc": "Diagnostique códigos de falha OBD-II, rastreie falhas elétricas e gerencie um fluxo de trabalho real de reparação automóvel.",
  "sim.marine-vessel.title": "Rastreamento de Embarcações Marítimas e Logística Marítima",
  "sim.marine-vessel.desc": "Comande uma frota global — acompanhe navios, navegue em congestionamentos de porto, emergências meteorológicas e atrasos de canais.",
