  "akinator.howTo.1": "Pense em qualquer personagem real ou fictício",
  "akinator.howTo.2": "Responda as perguntas com honestidade (Sim/Provavelmente/Não sei/Provavelmente não/Não)",
  "akinator.howTo.3": "A IA reduz os candidatos com cada resposta",
  "akinator.howTo.4": "Veja se o Akinator consegue adivinhar o seu personagem em até 20 perguntas!",
  "neonbreach.howTo.1": "Observe com atenção a sequência de nós acesos",
