  "neonbreach.howTo.3": "Cada nível correto adiciona mais um nó para lembrar",
  "neonbreach.howTo.4": "Um toque errado e o firewall te pega!",
  "earmaster.howTo.1": "Ouça com atenção a nota musical que está sendo tocada",
