  "earmaster.howTo.4": "Complete 10 rodadas para ver sua pontuação final",
  "uno.howTo.1": "Combine o cartão do topo da pilha por cor ou número",
  "uno.howTo.2": "Toque em um cartão na sua mão para jogar",
  "uno.howTo.3": "Se não houver combinação, toque em Comprar para adicionar um cartão",
  "uno.howTo.4": "Quem esvazia a mão primeiro vence!",
  "briscola.howTo.1": "Briscola é um jogo de cartas italiano de truque",
  "briscola.howTo.2": "O naipe de trunfo (Briscola) vence todos os outros naipes",
  "briscola.howTo.3": "Vença truques para ganhar pontos — Ás=11, 3=10, Rei=4, Dama=3, Valete=2",
  "briscola.howTo.4": "A maior pontuação depois que todas as cartas forem jogadas vence",
  "card99.howTo.1": "Jogue cartas para manter a soma em andamento em até 99",
  "card99.howTo.2": "Cartas especiais: Rei=0, Dama=conservar, Valete=−10, Ás=1 ou 11",
  "card99.howTo.3": "Ao ultrapassar 99 com a soma, você perde uma vida",
  "card99.howTo.4": "Ganha quem ficar por último com vidas!",
  "dominoes.howTo.1": "Combine os números nas pontas da corrente de dominós",
  "dominoes.howTo.2": "Jogue as peças da sua mão que combinam com uma ponta aberta",
  "dominoes.howTo.3": "Compre da pilha se não conseguir jogar",
  "dominoes.howTo.4": "Vence quem esvaziar a mão primeiro (ou tiver a menor soma de pips)!",
  "farkle.howTo.1": "Role 6 dados e separe quaisquer dados que pontuem",
  "farkle.howTo.2": "1s = 100 pts · 5s = 50 pts · Trinca = face × 100",
  "farkle.howTo.3": "Se NO dado marcar pontos ao rolar, isso é um FARKLE — perca sua vez!",
  "farkle.howTo.4": "Guarde seus pontos para mantê-los, ou role de novo para mais risco/recompensa",
  "quiz.howTo.1": "Responda a 20 perguntas de múltipla escolha o mais rápido possível",
  "quiz.howTo.2": "Cada pergunta tem 3 segundos — responda rápido!",
  "quiz.howTo.3": "Respostas corretas mais rápidas ganham mais pontos bônus",
  "quiz.howTo.4": "Complete todas as perguntas para ver sua classificação final",
