  "legal.privacy.collect.messaging.heading": "Mensagens do Facebook Messenger e do Instagram Direct",
  "legal.privacy.collect.messaging.text": "Quando você envia uma mensagem a uma página ou conta da Visionex no Facebook Messenger ou no Instagram Direct, a Meta nos transmite o texto que você escreveu, o identificador restrito que ela mantém sobre você (um ID vinculado à página ou à conta do Instagram, não o seu perfil, e-mail ou telefone), o identificador da mensagem e o horário de envio. Guardamos esses dados para ler sua dúvida, manter a conversa em ordem, evitar responder duas vezes à mesma mensagem e encaminhá-la a uma pessoa quando o atendimento automatizado não for suficiente. O texto da sua mensagem é processado por fornecedores externos de inteligência artificial para gerar uma resposta. Nunca recebemos sua senha do Facebook ou do Instagram, sua lista de amigos ou seguidores, nem os dados do seu perfil.",
  "legal.privacy.third.meta.name": "Meta Platforms (Facebook Messenger, Instagram Direct, WhatsApp)",
  "legal.privacy.third.meta.purpose": "Entrega as mensagens que você envia à Visionex pelo Messenger, Instagram Direct ou WhatsApp e nos permite devolver nossas respostas. A Meta trata essas mensagens em suas próprias plataformas segundo seus termos e sua política de privacidade.",
  "legal.privacy.deletionLink": "Para solicitar a exclusão dos dados que recebemos do Facebook Messenger ou do Instagram Direct, siga as instruções em",
