  "legal.dataDeletion.intro": "Esta página explica como solicitar a exclusão dos dados que a Visionex mantém sobre você, incluindo os que recebemos da Meta quando você nos escreveu pelo Facebook Messenger ou pelo Instagram Direct.",
  "legal.dataDeletion.howTitle": "Como solicitar a exclusão",
  "legal.dataDeletion.step1": "Envie-nos um e-mail com o assunto “Solicitação de exclusão de dados”.",
  "legal.dataDeletion.step2": "Informe a que serviço os dados se referem — por exemplo, uma mensagem enviada à página da Visionex no Facebook Messenger ou no Instagram Direct — e aproximadamente quando você nos contatou, para que possamos localizar a conversa correta. Se você tiver uma conta na Visionex, envie a solicitação a partir do e-mail cadastrado nela.",
  "legal.dataDeletion.step3": "Confirmamos o recebimento da solicitação, excluímos o que mantemos e respondemos informando o que foi removido.",
  "legal.dataDeletion.contact": "Envie as solicitações para",
  "legal.dataDeletion.whatTitle": "O que é excluído",
  "legal.dataDeletion.whatBody": "No caso do Facebook Messenger e do Instagram Direct, excluímos o registro da conversa que mantemos: o texto que você enviou, as respostas que enviamos, o identificador restrito que a Meta nos forneceu sobre você, os identificadores das mensagens e os horários. No caso de uma conta da Visionex, excluímos ou anonimizamos os dados pessoais vinculados a ela. Não podemos excluir nada que a Meta mantenha em suas próprias plataformas: a cópia da conversa na sua caixa do Messenger ou do Instagram pertence à sua conta Meta e pode ser apagada por você mesmo por lá.",
  "legal.dataDeletion.timingTitle": "Quanto tempo leva",
  "legal.dataDeletion.timingBody": "Procuramos concluir a exclusão em até 30 dias após a confirmação da sua solicitação. Quando somos obrigados a manter um registro limitado — por segurança, prevenção a fraudes, resolução de disputas ou obrigação legal — guardamos apenas o necessário e excluímos o restante.",
